# Enterprise software courses: content in our own words. Generic titles; no vendor text copied.
# Module tuple: (level, title, bloom, hours, intro, points, example, activity, standard, slides[(title, note)])
LV = {1: 'L1 Basic', 2: 'L2 Awareness', 3: 'L3 Foundation', 4: 'L4 Practitioner', 5: 'L5 Specialist', 6: 'L6 Advanced', 7: 'L7 Super expert'}

COURSES = []

def C(**k): COURSES.append(k)

# ---------------------------------------------------------------- 1 CRM
C(slug='ent-crm-administration', title='Customer Relationship Management Administration and Sales Process',
  short='Run a cloud CRM from first login to a governed, reported sales and service operation.',
  sub='Cloud CRM platform', who='Sales staff, channel managers, support agents, junior admins, career changers.',
  jobs=[('CRM administrator', 'Sets up users, access, fields and reports'), ('Sales operations analyst', 'Keeps pipeline data clean and reports it'), ('Channel manager', 'Plans and reviews partners inside the CRM'), ('Support team lead', 'Runs cases, queues and service levels'), ('CRM consultant', 'Designs the whole sales-to-service flow')],
  mods=[
 (1, 'Finding your way around', 'Remember', 2, 'A CRM is one shared notebook about customers. Before you change anything, learn where things are and what the words mean.',
  ['Learn the main objects: lead (a possible customer), account (a company), contact (a person), opportunity (a possible sale), case (a problem to fix).', 'Learn the screen parts: app menu, tabs, record page, list view, search bar.', 'Know who to ask: your administrator first, then the help page, then a super-user group.'],
  'A sales person opens an account, sees three contacts and one open opportunity, and finds the last visit note in under a minute.',
  'Open the practice org. Find one lead, one account, one contact, one opportunity and one case. Write the object name and the one-line meaning of each.', 'All five found; each described in your own words; no data changed.',
  [('Five objects in one picture', 'Draw lead to account, contact, opportunity, case. Say each word aloud. Ask the learner to point to each on screen.'), ('Where do I click?', 'Walk through app menu, tabs, search. Notes: keep to ten minutes; let the learner drive.')]),
 (2, 'Who can see and change what', 'Understand', 2, 'Access rules protect customers and the business. Three layers decide what a person sees: the profile or role, the sharing rules and the field settings.',
  ['Profile or permission set: what a person can do (read, create, edit, delete).', 'Role and sharing: whose records a person can see (own, team, all).', 'Field settings: which fields are hidden, read-only or required.', 'Least access first: give the smallest access that does the job.'],
  'A new support agent can see all cases in their region but only the contact name and phone on an account, not the contract value.',
  'Draw the access map for three job roles in a small company. For each, list objects they can read, edit and delete.', 'Map covers three roles; no role has delete on accounts unless justified in one sentence.',
  [('Three layers of access', 'Show who/what/which-fields as stacked layers. Note: avoid giving everyone full access for convenience.'), ('Least access', 'Give one example of too much access and the harm it can cause.')]),
 (3, 'Campaign to lead to account', 'Apply', 3, 'Marketing and sales meet at the lead. Good lead handling means every lead has an owner, a source, a next step and a clear end: converted or closed with a reason.',
  ['Create a campaign with a goal, budget and members.', 'Capture leads with a form; check for duplicates before creating.', 'Score and route leads by simple rules (region, product, size).', 'Convert a qualified lead into an account, contact and opportunity; close others with a reason.'],
  'A webinar brings 120 sign-ups. 80 are new leads, 40 match existing contacts. 22 are qualified and converted; 58 are closed with a reason and a nurture tag.',
  'Create one campaign, add 10 practice leads, route them by region, convert 3, close 2 with reasons.', 'No duplicate accounts; every lead has an owner and a status; reasons recorded.',
  [('Lead life cycle', 'New, working, converted, closed. Note: a lead must never sit without an owner.'), ('Duplicate check', 'Show a match rule; explain why duplicates damage reports.')]),
 (4, 'Opportunities and the sales process', 'Apply', 4, 'An opportunity moves through stages with proof at each step. The stage must tell the truth about the customer, not the hope of the seller.',
  ['Define stages and the exit proof for each (need confirmed, quote sent, decision maker met, terms agreed).', 'Record amount, close date, next step and competitor field (generic, no names in reports).', 'Add products, price lists and a quote; send for approval above a limit.', 'Forecast: commit, best case, pipeline, using stage and date together.'],
  'A 40,000 opportunity at stage Quote sent has a next step dated within 7 days; if none, the report flags it red.',
  'Build a four-stage path with exit proof; create two opportunities; produce a quote; set a forecast category.', 'Each stage has written exit proof; every open opportunity has a dated next step.',
  [('Stage, proof, next step', 'One slide per stage with the proof needed. Note: stages describe the customer, not the seller.'), ('Quote and approval', 'Explain the discount limit and who approves.')]),
 (5, 'Accounts, partners and channel plans', 'Analyse', 4, 'Large accounts and partners need a plan, not only a record. Segment accounts, plan the year, and review on a calendar.',
  ['Segment accounts by size and potential (for example A, B, C) and set visit and review frequency.', 'Account plan: goals, key people, offers, risks, actions with dates.', 'Partner plan: targets, business reviews (at least four a year for important partners), end-period review and a close-and-renew step.', 'Visit report: purpose, people, outcome, next action, logged within 24 hours.'],
  'A partner is rated B, gets four reviews a year, and the plan from last year is closed and copied forward with new targets.',
  'Write an account plan and a partner plan for one practice account; log two visit reports.', 'Plans have goals with numbers, dated actions and a review calendar; reports logged with next actions.',
  [('Segment, plan, review', 'Show the circle: plan, act, review, close, renew. Note: the circle ends only if the relationship ends.'), ('Good visit report', 'Show a good and a weak report side by side.')]),
 (6, 'Service: cases, queues and service levels', 'Evaluate', 4, 'Service turns a promise into a measured routine. Cases need a queue, a clock, an owner and a clear close.',
  ['Case flow: received, assigned, working, waiting for customer, solved, closed with a reason.', 'Entitlements and service levels: which customer gets which response and fix times.', 'Channels: email, portal, chat; one case for one problem.', 'Measure: first response time, time to solve, reopen rate, customer score.'],
  'Gold customers get a 1-hour response; the report shows 92% met in March and lists the 8% missed with causes.',
  'Set up a queue with two service levels; process ten practice cases; build a service dashboard.', 'Dashboard shows the four measures; at least 90% of practice cases within their clocks.',
  [('A case has a clock', 'Explain start, pause (waiting for customer), stop. Note: pause rules must be fair.'), ('Four service numbers', 'Define each in one line.')]),
 (7, 'Governance, data quality and change', 'Create', 5, 'At the top level you protect the whole system: clean data, tested changes, training and a support route.',
  ['Data quality: required fields, validation rules, duplicate rules, monthly clean-up report.', 'Change control: ideas list, sandbox test, release note, rollback plan.', 'Network of champions: a person per team who trains, collects ideas and helps others.', 'Audit: who changed what and when; yearly access review.'],
  'A new required field is tested in a sandbox with 10 users, released on a Friday with a one-page note, and checked on Monday for errors.',
  'Write a governance pack: data rules, change steps, champion plan, yearly review.', 'Pack passes review: each rule has an owner, a test and a date; rollback described.',
  [('Four guards', 'Data, change, people, audit. Note: governance should help people, not slow them.'), ('Release note', 'Show a one-page template.')]),
 ])

# ---------------------------------------------------------------- 2 Creative / document tools
C(slug='ent-creative-document-suite', title='Creative and Document Suite Practice: Design, PDF and Brand Control',
  short='Produce, protect and manage brand-safe designs and documents with a professional creative suite.',
  sub='Creative cloud suite', who='Designers, marketers, office staff, teachers, small-business owners.',
  jobs=[('Junior designer', 'Makes posters, social posts and layouts'), ('Document controller', 'Owns PDF forms, signatures and archive'), ('Brand coordinator', 'Keeps colours, fonts and logos correct'), ('Marketing assistant', 'Turns text into finished pieces'), ('Creative operations lead', 'Runs libraries, licences and review flow')],
  mods=[
 (1, 'The tools and the file types', 'Remember', 2, 'Know which tool does which job and which file to save.', ['Raster (photos) versus vector (logos and shapes).', 'Layout tool, photo tool, drawing tool, PDF tool.', 'Save an editable source and an export; name files with date and version.'], 'A logo is drawn as a vector so it prints sharp on a card and on a banner.', 'List five jobs and choose the tool and file type for each.', 'Five correct pairs; file names follow the naming rule.', [('Photo or drawing?', 'Show a zoomed photo and a zoomed logo. Note: pixels blur, vectors stay sharp.'), ('Source and export', 'Why keep both.')]),
 (2, 'Layout, type and colour basics', 'Understand', 2, 'Good design is clear before it is beautiful: one message, strong contrast, readable type.', ['Grid and spacing: align, repeat, leave room.', 'Two fonts at most; size shows importance.', 'Colour: brand palette, contrast checked for reading.'], 'A flyer with one headline, one picture and one action reads in 5 seconds.', 'Design one A4 flyer from a text brief.', 'One message; contrast passes; two fonts; peers recall the action.', [('One message', 'Remove everything that does not serve the message.'), ('Contrast', 'Show a pass and a fail.')]),
 (3, 'Photo editing and export', 'Apply', 3, 'Edit without damaging the original and export for the right place.', ['Use layers and non-destructive edits.', 'Crop, straighten, correct light and colour.', 'Export sizes: print, web, social; check file size.'], 'A 12 MB photo becomes a 300 KB web image that still looks clean.', 'Edit three photos and export each in two sizes.', 'Originals untouched; web files under 500 KB; no visible damage.', [('Layers', 'Show a layer stack; note that the original stays safe.'), ('Right size, right place', 'A table of sizes.')]),
 (4, 'Documents, PDF, forms and signatures', 'Apply', 3, 'Documents are evidence. Make them readable, fillable and signed correctly.', ['Create, combine, compress and protect a PDF.', 'Make a fillable form with required fields.', 'Request an electronic signature; keep the audit trail.', 'Make it accessible: headings, alt text, reading order.'], 'A three-page agreement is signed by two people in one day with a full audit record.', 'Create a fillable form and send it for signature to a practice partner.', 'Form works; signature trail kept; accessibility check passes.', [('Document journey', 'Create, fill, sign, store.'), ('Accessible by design', 'Headings and alt text.')]),
 (5, 'Brand systems and shared libraries', 'Analyse', 3, 'A brand is a set of rules people can find and follow.', ['Library: colours, fonts, logos, templates.', 'Templates with locked and open parts.', 'Review flow: draft, comment, approve, publish.'], 'Ten staff make posters from one template; only the text and picture change.', 'Build a small brand kit and two templates; test with a peer.', 'Peer produces a correct piece in 15 minutes without help.', [('Rules people can find', 'Where the kit lives.'), ('Locked and open', 'What users may change.')]),
 (6, 'Campaign production at scale', 'Evaluate', 4, 'Make many pieces fast and keep quality.', ['Batch and automate repeat edits.', 'Version for each language and market.', 'Check list before publish: facts, spelling, rights, accessibility.', 'Track results and learn.'], 'One campaign becomes 24 pieces in 3 languages with one check list.', 'Plan and produce a 12-piece campaign with a check list and results sheet.', 'All pieces pass the check list; results sheet compares two versions.', [('One idea, many pieces', 'Show the family of pieces.'), ('Check list', 'Facts, rights, access.')]),
 (7, 'Creative operations and governance', 'Create', 4, 'At the top you manage people, licences, rights and cost.', ['Licence and seat plan; remove unused seats.', 'Rights register for pictures, fonts and music.', 'Archive and retention rules.', 'Training and onboarding plan.'], 'A rights register stops a picture being used after its licence ended.', 'Write an operations pack: seats, rights register, archive rule, onboarding.', 'Pack has owners, dates and a yearly review.', [('Rights register', 'Columns and examples.'), ('Seat review', 'Cost saved.')]),
 ])

# ---------------------------------------------------------------- 3 Database and finance applications
C(slug='ent-database-finance-applications', title='Enterprise Database and Finance Applications Practice',
  short='Learn relational data, queries, and the core finance flows of a large business application suite.',
  sub='Enterprise database and applications platform', who='Accountants, data staff, junior developers, finance operations staff, career changers.',
  jobs=[('Database support analyst', 'Runs queries and checks data'), ('Finance systems analyst', 'Maintains ledger, payables, receivables'), ('Report developer', 'Builds management reports'), ('Application support lead', 'Handles incidents and changes'), ('Finance systems architect', 'Designs integration and controls')],
  mods=[
 (1, 'Data in tables', 'Remember', 2, 'A database is a set of tables linked by keys.', ['Table, row, column, key.', 'Types: text, number, date.', 'Why we do not store the same fact twice.'], 'A customer table and an invoice table are linked by customer number.', 'Sketch three linked tables for a small shop.', 'Keys named; no repeated facts.', [('Tables and keys', 'Draw two tables joined by a key.'), ('One fact, one place', 'Show a repeated-data problem.')]),
 (2, 'Asking questions with SQL', 'Apply', 3, 'SQL asks for exactly the rows and columns you need.', ['SELECT, FROM, WHERE, ORDER BY.', 'JOIN two tables.', 'GROUP BY with totals and counts.', 'Read before write: never run change commands on live data without a test.'], 'A query returns total sales per region for last month in one table.', 'Write six queries on the practice data set.', 'Six correct results; no write commands on live data.', [('Four words', 'SELECT FROM WHERE ORDER.'), ('Join', 'Show matching rows.')]),
 (3, 'The general ledger and chart of accounts', 'Understand', 3, 'The ledger is the book where every money event lands.', ['Chart of accounts: assets, liabilities, equity, income, expense.', 'Double entry: debit equals credit.', 'Periods, open and close.'], 'Buying a laptop for 1,000 debits equipment and credits bank.', 'Post ten practice journals and balance the trial.', 'Trial balance balances to zero.', [('Debit and credit', 'Two columns always equal.'), ('Open and close a period', 'Why we lock.')]),
 (4, 'Payables, receivables and cash', 'Apply', 4, 'Two flows run the business: what we owe and what we are owed.', ['Purchase to pay: order, receipt, invoice, match, pay.', 'Order to cash: quote, order, invoice, receipt, match.', 'Three-way match and approval limits.', 'Ageing report and follow-up.'], 'An invoice differs from the order by 3%; the match rule sends it for approval.', 'Process five purchase invoices and five sales invoices; run an ageing report.', 'All matched or explained; ageing report correct.', [('Two flows', 'Show both on one page.'), ('Three-way match', 'Order, receipt, invoice.')]),
 (5, 'Reporting and month-end close', 'Analyse', 4, 'A calm close is a checked list, done the same way each month.', ['Close calendar and owners.', 'Accruals, reconciliations, review.', 'Management reports and variance notes.'], 'Close takes 5 days instead of 9 because reconciliations run weekly.', 'Run a practice month-end close with a check list.', 'List fully ticked; variances explained in plain words.', [('Close calendar', 'Day-by-day.'), ('Variance note', 'Write one in plain words.')]),
 (6, 'Controls, security and audit', 'Evaluate', 4, 'Controls stop mistakes and fraud without stopping work.', ['Segregation of duties.', 'Approval limits and logs.', 'Backup, restore and access reviews.'], 'The person who creates a supplier cannot also pay that supplier.', 'Review a practice setup and list five control gaps with fixes.', 'Five real gaps, each with a fix and owner.', [('Never one person alone', 'Examples.'), ('Logs', 'What to record.')]),
 (7, 'Integration and performance design', 'Create', 5, 'At the top you design how systems talk and how fast they answer.', ['Interfaces: files, services, messages.', 'Indexes, query plans, batch windows.', 'Data migration plan with reconciliation.', 'Disaster recovery targets.'], 'A nightly interface moves 200,000 rows in 20 minutes after an index is added.', 'Write a design for a finance integration with migration and recovery plan.', 'Design reviewed; recovery time and data loss limits stated.', [('Interface map', 'Boxes and arrows.'), ('Index', 'Before and after timing.')]),
 ])

